"""Conformance tests for the Python fpsapcore port.

Run with `python3 -m unittest` from this directory, or just `python3
test_fairplay_sapcore.py`.

The expected values are not computed here. They come from
../../conformance/*.csv, generated by the Go reference in
fpsapcore. Computing them locally would make this a test that the
code agrees with itself, which is the failure mode this repository keeps
relearning.
"""

import os
import unittest

import fairplay_sapcore as F

CONF = os.path.join(os.path.dirname(__file__), "..", "..", "conformance")


def _rows(name):
    path = os.path.join(CONF, name)
    if not os.path.exists(path):
        raise AssertionError(
            "%s is missing. These tests fail rather than skip without it: a "
            "vector file that quietly disappears turns this into a suite that "
            "passes by doing nothing." % path)
    with open(path) as fh:
        rows = [line.strip().split(",") for line in fh
                if line.strip() and not line.startswith("#")]
    # ring_indices.csv carries a plain "i,x,y,z,w" header rather than a
    # commented one; drop any leading row that is not all numeric/hex.
    if rows and not all(c in "0123456789abcdef" for c in rows[0][0]):
        rows = rows[1:]
    return rows


class TestRingIndices(unittest.TestCase):
    """The unsigned-underflow trap. See ../../conformance/README.md."""

    def test_matches_conformance_file(self):
        rows = _rows("ring_indices.csv")
        self.assertEqual(len(rows), 840)
        for i, x, y, z, w in ((int(a), int(b), int(c), int(d), int(e))
                              for a, b, c, d, e in rows):
            self.assertEqual(F.RING_X[i], x, "ring x at %d" % i)
            self.assertEqual(F.RING_Y[i], y, "ring y at %d" % i)
            self.assertEqual(F.RING_Z[i], z, "ring z at %d" % i)
            self.assertEqual(F.RING_W[i], w, "ring w at %d" % i)

    def test_underflow_boundary(self):
        # Python's % on a negative operand returns a non-negative result, so
        # the naive form yields 55 here rather than a negative -- wrong, but
        # not obviously wrong, which is the danger.
        self.assertEqual(F.RING_X[0], 101)
        self.assertEqual((0 - 155) % 210, 55)
        self.assertEqual(F.RING_X[154], 45)
        # From 155 on, both forms agree.
        self.assertEqual(F.RING_X[155], 0)
        self.assertEqual(F.RING_X[156], 1)


class TestSapHash(unittest.TestCase):
    def test_golden_vectors(self):
        for block_hex, want in _rows("sap_hash.csv"):
            got = F.fairplay_sap_hash(bytes.fromhex(block_hex)).hex()
            self.assertEqual(got, want, "block %s..." % block_hex[:16])

    def test_rejects_wrong_length(self):
        with self.assertRaises(ValueError):
            F.fairplay_sap_hash(b"\x00" * 63)


class TestBridge(unittest.TestCase):
    def test_golden_vectors(self):
        for sap_hex, gp_hex, want in _rows("bridge_x9head.csv"):
            got = F.bridge_x9_head_for_sap(
                bytes.fromhex(sap_hex), bytes.fromhex(gp_hex)).hex()
            self.assertEqual(got, want)

    def test_rejects_wrong_length(self):
        with self.assertRaises(ValueError):
            F.bridge_x9_head_for_sap(b"\x00" * 127, b"\x00" * 128)


class TestTheVectorsActuallyDiscriminate(unittest.TestCase):
    """Prove the corpus can fail, by breaking the code on purpose.

    A passing suite means nothing unless the vectors reject a wrong
    implementation. Each case here reintroduces a real porting mistake and
    asserts that the corpus catches it.
    """

    def setUp(self):
        self._saved = (F.RING_X, F.rotate_or_zero, F.wide_seed)

    def tearDown(self):
        F.RING_X, F.rotate_or_zero, F.wide_seed = self._saved

    def _failures(self):
        return sum(1 for blk, want in _rows("sap_hash.csv")
                   if F.fairplay_sap_hash(bytes.fromhex(blk)).hex() != want)

    def test_naive_ring_index_is_caught(self):
        F.RING_X = bytes(((i - 155) % 210) for i in range(840))
        self.assertEqual(self._failures(), 39)

    def test_rotate_or_zero_as_plain_rotate_is_caught(self):
        F.rotate_or_zero = lambda v, c: F._rotl8(v & 255, c & 255)
        self.assertGreater(self._failures(), 30)

    def test_wide_seed_masked_to_eight_bits_is_caught(self):
        def masked(value, count):
            count &= 255
            if count == 0:
                return F.SAP_SEED[0]
            return F.SAP_SEED[(((value << count) | (value >> (8 - count))) & 255) % 21]
        F.wide_seed = masked
        self.assertGreater(self._failures(), 30)

    def test_the_all_zero_block_proves_nothing(self):
        """The one vector that survives a broken index table.

        A ring loop over an all-zero buffer stays all-zero whichever cells it
        reads, so this block produces the right answer even when the index
        derivation is wrong. It is the reason the corpus has 40 vectors and
        not one, and the reason a smoke test is not a test.
        """
        zero = b"\x00" * 64
        expected = dict(_rows("sap_hash.csv"))[zero.hex()]
        F.RING_X = bytes(((i - 155) % 210) for i in range(840))
        self.assertEqual(F.fairplay_sap_hash(zero).hex(), expected)


if __name__ == "__main__":
    unittest.main(verbosity=2)
